import re


def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Empty string")

    matches = re.findall(r'\d+[hms]', s)
    if not matches or ''.join(matches) != s:
        raise ValueError(f"Invalid input: {s}")

    total = 0
    for match in matches:
        num_str, unit = re.match(r'(\d+)([hms])', match).groups()
        num = int(num_str)
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        else:
            total += num

    return total
```

