def sa_id_valid(id_number: str) -> bool:
    if len(id_number) != 13 or not id_number.isdigit():
        return False

    yy = int(id_number[0:2])
    mm = int(id_number[2:4])
    dd = int(id_number[4:6])

    if mm < 1 or mm > 12:
        return False

    days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    if mm == 2:
        max_days = 29 if yy % 4 == 0 else 28
    else:
        max_days = days_in_month[mm]

    if dd < 1 or dd > max_days:
        return False

    total = 0
    for i, ch in enumerate(reversed(id_number)):
        digit = int(ch)
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
```

